gid_t new_rgid = 1001;
gid_t new_egid = 2001;

// Set both Real and Effective GIDs
int s1 = setregid32(new_rgid, new_egid);

// Change only the Effective GID (using -1 for Real)
// Useful for temporarily dropping privileges
int s2 = setregid32(-1, new_rgid);

// Change only the Real GID (requires CAP_SETGID)
int s3 = setregid32(new_egid, -1);

// Permanently drop privileges (set both to current real GID)
int s4 = setregid32(getgid(), getgid());

if (s1 == -1) { /* Handle EPERM, EAGAIN, EINVAL */ }
